insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('c8000000-0000-0000-0000-000000000001', 'ukmla', 'ba9e03b8-7838-4187-9712-8ce1d2cc9408',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('c8000000-0000-0000-0000-000000000001', 'A', 'Discharge with oral antibiotics and GP follow-up in one week', false, 'Ruled out because active signs of peritonism require urgent surgical assessment, not discharge into the community.', 1),
('c8000000-0000-0000-0000-000000000001', 'B', 'Reassure and advise analgesia only, as this is likely gastroenteritis', false, 'Ruled out because migratory pain localising to a single peritonitic site is not typical of gastroenteritis, which usually causes diffuse pain without focal guarding.', 2),
('c8000000-0000-0000-0000-000000000001', 'C', 'Arrange outpatient abdominal ultrasound in 2 weeks', false, 'Ruled out because delaying assessment risks perforation; a patient with peritonism needs same-day surgical review, not deferred outpatient imaging.', 3),
('c8000000-0000-0000-0000-000000000001', 'D', 'Commence broad-spectrum IV antibiotics alone with no surgical input, planning for non-operative management', false, 'Ruled out because although antibiotic-only strategies exist for selected uncomplicated cases, a patient with peritonism on examination requires surgical assessment rather than antibiotics without any surgical involvement.', 4),
('c8000000-0000-0000-0000-000000000001', 'E', 'Urgent surgical referral for appendicectomy', true, $x$Correct. Migratory periumbilical-to-right-iliac-fossa pain with localised peritonism (guarding, rebound and percussion tenderness, positive Rovsing's sign) is classic acute appendicitis; the next step is urgent surgical referral for operative management.$x$, 5),
('c8000000-0000-0000-0000-000000000002', 'A', 'Bilateral pleural effusions', false, 'Ruled out because pleural effusions are not the characteristic sign of a perforated viscus; they suggest other pathology such as heart failure or pneumonia.', 1),
('c8000000-0000-0000-0000-000000000002', 'B', 'Free air under the right hemidiaphragm', true, 'Correct. A rigid, guarded abdomen with absent bowel sounds and sudden severe pain in a patient on regular NSAIDs suggests a perforated peptic ulcer; free air under the diaphragm on an erect chest X-ray confirms pneumoperitoneum from perforation.', 2),
('c8000000-0000-0000-0000-000000000002', 'C', 'Widened mediastinum', false, 'Ruled out because a widened mediastinum is a sign of aortic dissection, not a perforated abdominal viscus.', 3),
('c8000000-0000-0000-0000-000000000002', 'D', 'Air-fluid levels in dilated small bowel loops', false, 'Ruled out because air-fluid levels are seen on an abdominal X-ray in bowel obstruction, not on an erect chest X-ray, and do not indicate perforation.', 4),
('c8000000-0000-0000-0000-000000000002', 'E', 'Cardiomegaly with pulmonary oedema', false, $x$Ruled out because this pattern reflects heart failure, which does not explain this patient's acute rigid abdomen.$x$, 5),
('c8000000-0000-0000-0000-000000000003', 'A', 'Immediate laparotomy without further resuscitation', false, 'Ruled out because uncomplicated adhesional obstruction is usually managed conservatively first; surgery is reserved for failed conservative management or signs of ischaemia.', 1),
('c8000000-0000-0000-0000-000000000003', 'B', 'Oral laxatives and high-fibre diet', false, 'Ruled out because oral intake should be stopped in obstruction, and laxatives will not relieve a mechanical obstruction.', 2),
('c8000000-0000-0000-0000-000000000003', 'C', 'Discharge home with outpatient CT abdomen in one week', false, 'Ruled out because active bowel obstruction requires inpatient management, not outpatient deferral.', 3),
('c8000000-0000-0000-0000-000000000003', 'D', 'Nil by mouth, IV fluid resuscitation, and nasogastric tube decompression', true, $x$Correct. Adhesional small bowel obstruction is initially managed conservatively with NBM, IV fluids, and NG decompression ('drip and suck'), reserving surgery for failure to resolve or signs of strangulation.$x$, 4),
('c8000000-0000-0000-0000-000000000003', 'E', 'Start oral antibiotics and encourage oral fluids', false, 'Ruled out because the patient should be kept nil by mouth in obstruction, and antibiotics are not first-line management of uncomplicated obstruction.', 5),
('c8000000-0000-0000-0000-000000000004', 'A', 'Acute pancreatitis', false, 'Ruled out because pancreatitis typically causes epigastric pain radiating to the back with a raised amylase/lipase, not pain out of proportion to soft examination findings with this degree of lactate elevation.', 1),
('c8000000-0000-0000-0000-000000000004', 'B', 'Diverticulitis', false, 'Ruled out because diverticulitis typically causes localised left iliac fossa tenderness with fever, rather than diffuse pain disproportionate to examination.', 2),
('c8000000-0000-0000-0000-000000000004', 'C', 'Acute mesenteric ischaemia secondary to embolism', true, 'Correct. Severe pain disproportionate to examination findings, a background of atrial fibrillation, and a markedly raised lactate are classic for acute mesenteric ischaemia from embolic occlusion of a mesenteric vessel.', 3),
('c8000000-0000-0000-0000-000000000004', 'D', 'Irritable bowel syndrome', false, 'Ruled out because IBS does not cause acute severe pain with a markedly raised lactate and white cell count; it is a chronic functional condition.', 4),
('c8000000-0000-0000-0000-000000000004', 'E', 'Constipation with overflow diarrhoea', false, 'Ruled out because this would not explain the severity of pain, the raised lactate, or the leucocytosis seen here.', 5),
('c8000000-0000-0000-0000-000000000005', 'A', 'Sepsis six bundle with IV fluids and broad-spectrum antibiotics, urgent CT abdomen, and surgical review', true, 'Correct. Generalised peritonism with septic shock in a patient with known diverticular disease is concerning for perforated diverticulitis; immediate sepsis six management alongside urgent CT and surgical review is required.', 1),
('c8000000-0000-0000-0000-000000000005', 'B', 'Oral antibiotics and outpatient colonoscopy in 6 weeks', false, 'Ruled out because this patient is septic with peritonism and needs immediate inpatient resuscitation, not outpatient management.', 2),
('c8000000-0000-0000-0000-000000000005', 'C', 'High-fibre diet advice and simple analgesia', false, 'Ruled out because this is appropriate for uncomplicated diverticular disease, not a patient with septic shock and peritonism suggesting perforation.', 3),
('c8000000-0000-0000-0000-000000000005', 'D', 'Immediate colonoscopy to confirm diagnosis', false, 'Ruled out because colonoscopy is contraindicated in suspected perforation due to the risk of insufflating air through the perforation and worsening contamination.', 4),
('c8000000-0000-0000-0000-000000000005', 'E', 'Discharge with safety-net advice to return if worse', false, 'Ruled out because this patient is critically unwell with septic shock and requires immediate admission and resuscitation, not discharge.', 5),
('c8000000-0000-0000-0000-000000000006', 'A', 'Immediate ERCP within 2 hours regardless of biliary obstruction status', false, 'Ruled out because ERCP is reserved for patients with evidence of ongoing common bile duct obstruction or cholangitis, not performed routinely and immediately in all gallstone pancreatitis.', 1),
('c8000000-0000-0000-0000-000000000006', 'B', 'Urgent laparotomy for pancreatic necrosectomy', false, 'Ruled out because surgery is not first-line management of acute pancreatitis; necrosectomy is reserved for specific complications such as infected necrosis, not the initial presentation.', 2),
('c8000000-0000-0000-0000-000000000006', 'C', 'Strict oral intake encouraged immediately to prevent malnutrition, with no IV fluids', false, 'Ruled out because initial management prioritises IV fluid resuscitation; oral intake is generally limited in the acute phase and reintroduced as tolerated.', 3),
('c8000000-0000-0000-0000-000000000006', 'D', 'IV fluid resuscitation, analgesia, and monitoring with severity scoring (e.g. Glasgow score)', true, 'Correct. Gallstone-related acute pancreatitis is managed supportively with aggressive IV fluids, analgesia, and severity stratification using a validated score, with treatment escalated according to severity.', 4),
('c8000000-0000-0000-0000-000000000006', 'E', 'Start prophylactic broad-spectrum antibiotics for all patients', false, 'Ruled out because antibiotics are not given routinely in acute pancreatitis unless there is evidence of infected necrosis or associated cholangitis.', 5),
('c8000000-0000-0000-0000-000000000007', 'A', 'Immediate emergency laparotomy and sigmoid colectomy', false, 'Ruled out because surgery is reserved for failed endoscopic decompression, recurrence, or signs of ischaemia/perforation, not first-line for an uncomplicated volvulus.', 1),
('c8000000-0000-0000-0000-000000000007', 'B', 'Sigmoidoscopy with flatus tube insertion for decompression', true, 'Correct. First-line management of uncomplicated sigmoid volvulus (no peritonism or perforation) is endoscopic decompression with flatus tube placement.', 2),
('c8000000-0000-0000-0000-000000000007', 'C', 'High-fibre diet and laxatives alone', false, 'Ruled out because this does not address an acute mechanical obstruction requiring decompression.', 3),
('c8000000-0000-0000-0000-000000000007', 'D', 'Barium enema as first-line treatment', false, 'Ruled out because barium enema is not the treatment of choice and barium is inappropriate if perforation risk exists; sigmoidoscopic decompression is preferred.', 4),
('c8000000-0000-0000-0000-000000000007', 'E', 'Discharge with outpatient colonoscopy', false, 'Ruled out because this patient has an acute obstruction requiring inpatient decompression, not outpatient deferral.', 5),
('c8000000-0000-0000-0000-000000000008', 'A', 'Reassure and review in 3 months', false, 'Ruled out because a suspicious lump with these features should not be observed without urgent assessment.', 1),
('c8000000-0000-0000-0000-000000000008', 'B', 'Prescribe antibiotics for presumed infection', false, 'Ruled out because there are no features of infection (erythema, fever, fluctuance); antibiotics do not address a suspicious discrete lump.', 2),
('c8000000-0000-0000-0000-000000000008', 'C', 'Arrange routine (non-urgent) referral in 3 months', false, 'Ruled out because red-flag features mandate urgent (2-week wait), not routine, referral.', 3),
('c8000000-0000-0000-0000-000000000008', 'D', 'Discharge with advice to return only if the lump grows', false, 'Ruled out because this delays assessment of a lump with concerning features that already warrants urgent referral.', 4),
('c8000000-0000-0000-0000-000000000008', 'E', 'Urgent (2-week wait) referral to a breast clinic for triple assessment', true, 'Correct. A discrete, hard, irregular breast lump with skin tethering in a woman over 30 is a red flag requiring urgent referral for triple assessment.', 5),
('c8000000-0000-0000-0000-000000000009', 'A', 'Invasive ductal carcinoma', false, 'Ruled out because carcinoma is typically firm, irregular, and fixed, and is far less common in this age group.', 1),
('c8000000-0000-0000-0000-000000000009', 'B', 'Breast abscess', false, 'Ruled out because there is no pain, erythema, warmth, or fluctuance to suggest an abscess.', 2),
('c8000000-0000-0000-0000-000000000009', 'C', 'Fibroadenoma', true, 'Correct. Fibroadenomas are the most common cause of a discrete breast lump in women under 30 and are classically smooth, mobile, and well-circumscribed.', 3),
('c8000000-0000-0000-0000-000000000009', 'D', $x$Paget's disease of the nipple$x$, false, 'Ruled out because there is no nipple/areolar skin change described.', 4),
('c8000000-0000-0000-0000-000000000009', 'E', 'Duct ectasia', false, 'Ruled out because duct ectasia typically presents with nipple discharge or a periareolar mass, not a discrete mobile lump like this.', 5),
('c8000000-0000-0000-0000-000000000010', 'A', 'Continue breastfeeding (or expressing) from the affected breast and start oral flucloxacillin', true, 'Correct. Lactational mastitis without a fluctuant collection is managed with continued breastfeeding/expressing and appropriate antibiotics (typically flucloxacillin covering Staphylococcus aureus).', 1),
('c8000000-0000-0000-0000-000000000010', 'B', 'Stop breastfeeding immediately and start IV antibiotics', false, 'Ruled out because stopping breastfeeding is not required and can worsen milk stasis; IV antibiotics are unnecessary for uncomplicated mastitis without systemic sepsis requiring admission.', 2),
('c8000000-0000-0000-0000-000000000010', 'C', 'Arrange ultrasound-guided drainage as first-line treatment', false, 'Ruled out because drainage is reserved for a confirmed fluctuant abscess, which is not present here.', 3),
('c8000000-0000-0000-0000-000000000010', 'D', 'Reassure with no treatment, as this will self-resolve without antibiotics', false, 'Ruled out because a fever with a tender, erythematous, indurated breast warrants antibiotic treatment, not simple reassurance.', 4),
('c8000000-0000-0000-0000-000000000010', 'E', 'Prescribe topical antifungal cream', false, 'Ruled out because this presentation is bacterial mastitis, not a fungal infection.', 5),
('c8000000-0000-0000-0000-000000000011', 'A', 'Reassurance that this is eczema and continue topical steroids', false, 'Ruled out because eczema of the nipple is typically bilateral and responds to steroids; a unilateral rash unresponsive to treatment must not be assumed benign.', 1),
('c8000000-0000-0000-0000-000000000011', 'B', 'Urgent referral for triple assessment including nipple/skin biopsy', true, $x$Correct. A unilateral, eczema-like nipple rash that fails to respond to topical treatment is Paget's disease of the nipple until proven otherwise, and is strongly associated with underlying ductal carcinoma; biopsy and triple assessment are required.$x$, 2),
('c8000000-0000-0000-0000-000000000011', 'C', 'Prescribe a course of oral antifungal treatment', false, 'Ruled out because there is no indication of a fungal cause, and this would delay diagnosis of a potentially malignant process.', 3),
('c8000000-0000-0000-0000-000000000011', 'D', 'Advise use of an emollient and review in 6 months', false, 'Ruled out because this delays investigation of a red-flag presentation strongly associated with malignancy.', 4),
('c8000000-0000-0000-0000-000000000011', 'E', 'Refer to dermatology only, with no breast assessment required', false, 'Ruled out because the underlying concern is breast malignancy, requiring breast triple assessment, not dermatology alone.', 5),
('c8000000-0000-0000-0000-000000000012', 'A', 'Reassure that this is a bruise and it will resolve, with no further action needed', false, 'Ruled out because a firm irregular lump with skin dimpling cannot be reliably distinguished from cancer clinically and requires formal assessment.', 1),
('c8000000-0000-0000-0000-000000000012', 'B', 'Arrange review in 6 months without imaging', false, 'Ruled out because this delays exclusion of malignancy in a lump with concerning features.', 2),
('c8000000-0000-0000-0000-000000000012', 'C', 'Prescribe antibiotics for a presumed haematoma infection', false, 'Ruled out because there are no signs of infection (fever, erythema, fluctuance) described.', 3),
('c8000000-0000-0000-0000-000000000012', 'D', 'Advise ice packs only and discharge', false, 'Ruled out because this does not address the need to exclude malignancy in a new discrete lump.', 4),
('c8000000-0000-0000-0000-000000000012', 'E', 'Urgent referral for triple assessment to exclude malignancy, despite the history of trauma', true, 'Correct. Fat necrosis can clinically mimic carcinoma with a firm, irregular lump and skin dimpling, and a history of trauma does not exclude malignancy; triple assessment is required to confirm the diagnosis.', 5),
('c8000000-0000-0000-0000-000000000013', 'A', 'Age over 50 alone', false, 'Ruled out because although age is a general risk factor for breast cancer, the specific concerning feature here is the character of the discharge itself.', 1),
('c8000000-0000-0000-0000-000000000013', 'B', 'Intermittent nature of the discharge', false, 'Ruled out because intermittent discharge alone is not the discriminating red-flag feature; the blood-staining and unilaterality are.', 2),
('c8000000-0000-0000-0000-000000000013', 'C', 'Unilateral, blood-stained nipple discharge', true, 'Correct. Unilateral, spontaneous, blood-stained nipple discharge is a red-flag feature requiring urgent breast clinic referral to exclude an underlying papilloma or carcinoma.', 3),
('c8000000-0000-0000-0000-000000000013', 'D', 'Absence of a palpable lump', false, 'Ruled out because malignancy (including intraductal papilloma or carcinoma) can present with abnormal discharge even without a palpable lump.', 4),
('c8000000-0000-0000-0000-000000000013', 'E', 'Absence of pain', false, 'Ruled out because malignant nipple discharge is typically painless; pain is not the discriminating feature here.', 5),
('c8000000-0000-0000-0000-000000000014', 'A', 'Urgent 2-week-wait referral to breast clinic for triple assessment to exclude inflammatory breast cancer', true, $x$Correct. Erythema and skin thickening with peau d'orange in a non-lactating woman that fails to respond to antibiotics is highly suspicious of inflammatory breast cancer and requires urgent triple assessment.$x$, 1),
('c8000000-0000-0000-0000-000000000014', 'B', 'Prescribe a second, broader-spectrum course of oral antibiotics', false, 'Ruled out because failure of a first antibiotic course in a non-lactating woman should prompt investigation for malignancy, not repeated empirical antibiotics.', 2),
('c8000000-0000-0000-0000-000000000014', 'C', 'Arrange incision and drainage under local anaesthetic', false, 'Ruled out because there is no fluctuant abscess described, and this would not address the underlying suspected malignancy.', 3),
('c8000000-0000-0000-0000-000000000014', 'D', 'Reassure that this is simply resistant mastitis and review in 4 weeks', false, 'Ruled out because this presentation outside lactation with axillary lymphadenopathy strongly suggests malignancy and needs urgent, not deferred, assessment.', 4),
('c8000000-0000-0000-0000-000000000014', 'E', 'Refer to dermatology for management of a presumed skin infection', false, 'Ruled out because the underlying concern is breast malignancy requiring urgent breast clinic assessment, not dermatology referral.', 5),
('c8000000-0000-0000-0000-000000000015', 'A', 'Reassure and treat empirically for haemorrhoids', false, 'Ruled out because the combination of weight loss and iron-deficiency anaemia should not be attributed to haemorrhoids without excluding a more serious cause.', 1),
('c8000000-0000-0000-0000-000000000015', 'B', 'Arrange routine outpatient referral in 3 months', false, 'Ruled out because red-flag features mandate urgent, not routine, referral.', 2),
('c8000000-0000-0000-0000-000000000015', 'C', 'Start oral iron replacement only, with no further investigation', false, 'Ruled out because the underlying cause of the anaemia must be investigated, particularly given the associated red-flag symptoms.', 3),
('c8000000-0000-0000-0000-000000000015', 'D', 'Urgent (2-week wait) referral for colonoscopy', true, 'Correct. Rectal bleeding with a change in bowel habit, weight loss, and iron-deficiency anaemia in a patient over 60 are red-flag features requiring urgent investigation for colorectal cancer.', 4),
('c8000000-0000-0000-0000-000000000015', 'E', 'Faecal calprotectin testing before considering referral', false, 'Ruled out because this delays urgent cancer pathway referral, which is indicated regardless of calprotectin results given his red-flag features.', 5),
('c8000000-0000-0000-0000-000000000016', 'A', 'Commence broad-spectrum IV antibiotics', false, 'Ruled out because there is no evidence of acute diverticulitis or infection here; antibiotics are not indicated for uncomplicated diverticular disease.', 1),
('c8000000-0000-0000-0000-000000000016', 'B', 'Arrange emergency laparotomy', false, 'Ruled out because there is no evidence of perforation, abscess, or peritonism requiring emergency surgery.', 2),
('c8000000-0000-0000-0000-000000000016', 'C', 'Prescribe long-term prophylactic antibiotics', false, 'Ruled out because long-term antibiotics are not part of standard management of uncomplicated diverticular disease.', 3),
('c8000000-0000-0000-0000-000000000016', 'D', 'Advise a strict low-fibre diet indefinitely', false, 'Ruled out because a high-fibre, not low-fibre, diet is recommended for uncomplicated diverticular disease.', 4),
('c8000000-0000-0000-0000-000000000016', 'E', 'Advise a high-fibre diet and simple analgesia, with safety-net advice', true, 'Correct. Uncomplicated diverticular disease without signs of infection or complication is managed conservatively with dietary fibre and analgesia.', 5),
('c8000000-0000-0000-0000-000000000017', 'A', 'Immediate surgical sphincterotomy', false, 'Ruled out because sphincterotomy is reserved for chronic fissures that fail an adequate trial of conservative and topical treatment, not first-line therapy.', 1),
('c8000000-0000-0000-0000-000000000017', 'B', 'Dietary fibre and fluid advice, stool softeners, and topical GTN or diltiazem', true, 'Correct. First-line management of an anal fissure is conservative: dietary/fluid measures with stool softeners, alongside topical GTN or diltiazem to relax the internal anal sphincter and promote healing.', 2),
('c8000000-0000-0000-0000-000000000017', 'C', 'Botulinum toxin injection as first-line treatment', false, 'Ruled out because botulinum toxin is generally used as a second-line treatment after topical therapy has failed.', 3),
('c8000000-0000-0000-0000-000000000017', 'D', 'Oral opioid analgesia as first-line treatment', false, 'Ruled out because opioids worsen constipation, which would exacerbate the underlying cause of the fissure.', 4),
('c8000000-0000-0000-0000-000000000017', 'E', 'Reassurance only, with no treatment required', false, 'Ruled out because active treatment is needed to relieve pain and promote healing of a symptomatic fissure.', 5),
('c8000000-0000-0000-0000-000000000018', 'A', 'Dietary fibre, adequate fluid intake, and topical treatment, with outpatient banding if symptoms persist', true, 'Correct. Conservative measures are first-line for symptomatic internal haemorrhoids, with banding or other outpatient procedures reserved for persistent symptoms.', 1),
('c8000000-0000-0000-0000-000000000018', 'B', 'Immediate haemorrhoidectomy', false, 'Ruled out because surgery is reserved for cases refractory to conservative and outpatient procedural management, not first-line for this presentation.', 2),
('c8000000-0000-0000-0000-000000000018', 'C', 'Urgent 2-week-wait referral for suspected colorectal cancer', false, 'Ruled out because the bleeding here is painless, coats the stool, and proctoscopy has already confirmed a clear benign cause with no other red-flag features.', 3),
('c8000000-0000-0000-0000-000000000018', 'D', 'No treatment required, as haemorrhoids always resolve spontaneously', false, 'Ruled out because symptomatic haemorrhoids often benefit from conservative measures rather than being left entirely untreated.', 4),
('c8000000-0000-0000-0000-000000000018', 'E', 'Long-term daily laxative suppositories as sole management', false, 'Ruled out because this is not the recommended first-line approach; dietary fibre, fluids, and topical treatment are preferred.', 5),
('c8000000-0000-0000-0000-000000000019', 'A', 'Discharge home with oral mesalazine only', false, 'Ruled out because acute severe colitis meeting these criteria requires inpatient IV treatment, not outpatient oral therapy alone.', 1),
('c8000000-0000-0000-0000-000000000019', 'B', 'Start an anti-diarrhoeal agent (e.g. loperamide) to reduce stool frequency', false, 'Ruled out because anti-motility agents can precipitate toxic megacolon in acute severe colitis and should be avoided.', 2),
('c8000000-0000-0000-0000-000000000019', 'C', 'Immediate total colectomy without a trial of medical therapy', false, 'Ruled out because IV corticosteroids are first-line for acute severe colitis, with surgery reserved for those who fail to respond to medical therapy.', 3),
('c8000000-0000-0000-0000-000000000019', 'D', 'Admission for IV corticosteroids, VTE prophylaxis, and monitoring for signs of toxic megacolon', true, 'Correct. This meets criteria for acute severe ulcerative colitis, which requires hospital admission, IV corticosteroids, and close monitoring for toxic megacolon.', 4),
('c8000000-0000-0000-0000-000000000019', 'E', 'Reassure and advise dietary changes alone', false, 'Ruled out because this systemic, severe flare requires urgent inpatient medical treatment, not reassurance and dietary advice.', 5),
('c8000000-0000-0000-0000-000000000020', 'A', 'Ulcerative colitis', false, 'Ruled out because ulcerative colitis characteristically causes bloody diarrhoea confined to the colon/rectum and is not associated with perianal fistulae.', 1),
('c8000000-0000-0000-0000-000000000020', 'B', 'Irritable bowel syndrome', false, 'Ruled out because IBS does not cause weight loss, anaemia, raised inflammatory markers, or perianal fistulating disease.', 2),
('c8000000-0000-0000-0000-000000000020', 'C', $x$Crohn's disease$x$, true, $x$Correct. Right iliac fossa/terminal ileal symptoms with weight loss, anaemia, and perianal fistulating disease are characteristic of Crohn's disease.$x$, 3),
('c8000000-0000-0000-0000-000000000020', 'D', 'Acute appendicitis', false, 'Ruled out because the chronic, relapsing course with systemic features and perianal disease is not consistent with acute appendicitis.', 4),
('c8000000-0000-0000-0000-000000000020', 'E', 'Diverticulitis', false, 'Ruled out because diverticulitis typically affects older patients with left-sided symptoms, not a young woman with right iliac fossa pain and perianal fistula.', 5),
('c8000000-0000-0000-0000-000000000021', 'A', 'Ischaemic colitis', true, $x$Correct. Sudden left-sided pain with bloody diarrhoea and 'thumbprinting' on X-ray in a patient with vascular risk factors is characteristic of ischaemic colitis affecting a watershed area of the colon.$x$, 1),
('c8000000-0000-0000-0000-000000000021', 'B', 'Ulcerative colitis', false, 'Ruled out because the sudden onset in an older patient with vascular risk factors, rather than a chronic relapsing course, favours an ischaemic rather than inflammatory cause.', 2),
('c8000000-0000-0000-0000-000000000021', 'C', 'Acute mesenteric ischaemia (small bowel)', false, 'Ruled out because this typically causes diffuse small bowel ischaemia with pain out of proportion to examination, rather than the colonic thumbprinting seen here.', 3),
('c8000000-0000-0000-0000-000000000021', 'D', 'Infective colitis', false, 'Ruled out because there is no reported diarrhoeal illness contact, travel, or food history, and the imaging and risk factor profile favour an ischaemic cause.', 4),
('c8000000-0000-0000-0000-000000000021', 'E', 'Diverticulitis', false, 'Ruled out because diverticulitis typically presents with localised tenderness and fever rather than the thumbprinting pattern of ischaemic colitis.', 5),
('c8000000-0000-0000-0000-000000000022', 'A', 'Reassurance only, with no follow-up required', false, 'Ruled out because a symptomatic hernia carries an ongoing risk of complications and should be referred for elective repair, not left unaddressed.', 1),
('c8000000-0000-0000-0000-000000000022', 'B', 'Elective referral for surgical repair', true, 'Correct. A symptomatic, reducible inguinal hernia is generally managed with elective surgical repair to reduce the risk of complications such as incarceration or strangulation.', 2),
('c8000000-0000-0000-0000-000000000022', 'C', 'Urgent (same-day) surgical exploration', false, 'Ruled out because there are no signs of strangulation or incarceration; this can be managed electively rather than as an emergency.', 3),
('c8000000-0000-0000-0000-000000000022', 'D', 'Advise a truss as definitive treatment instead of surgery', false, 'Ruled out because a truss is not a definitive treatment and is reserved for patients unfit for surgery; it does not reliably prevent complications.', 4),
('c8000000-0000-0000-0000-000000000022', 'E', 'Discharge with advice that the hernia will resolve spontaneously', false, 'Ruled out because inguinal hernias do not resolve spontaneously in adults and require surgical repair if symptomatic.', 5),
('c8000000-0000-0000-0000-000000000023', 'A', 'Attempt forceful manual reduction in the emergency department before any other intervention', false, 'Ruled out because forceful reduction risks pushing non-viable, strangulated bowel back into the abdomen and should not be attempted when strangulation is suspected.', 1),
('c8000000-0000-0000-0000-000000000023', 'B', 'Discharge with outpatient elective hernia repair booking', false, 'Ruled out because this presentation suggests strangulation, which is a surgical emergency, not something to manage electively as an outpatient.', 2),
('c8000000-0000-0000-0000-000000000023', 'C', 'Reassure and advise applying a warm compress at home', false, 'Ruled out because this delays emergency treatment of a strangulated hernia.', 3),
('c8000000-0000-0000-0000-000000000023', 'D', 'Prescribe oral antibiotics only and review in the community in 48 hours', false, 'Ruled out because this patient needs urgent inpatient resuscitation and surgical review, not community follow-up with oral antibiotics alone.', 4),
('c8000000-0000-0000-0000-000000000023', 'E', 'Nil by mouth, IV fluid resuscitation, analgesia, and urgent surgical review for emergency repair', true, 'Correct. A previously reducible hernia that becomes irreducible, tender, and erythematous with systemic signs suggests strangulation, a surgical emergency requiring urgent resuscitation and operative intervention.', 5),
('c8000000-0000-0000-0000-000000000024', 'A', 'Inguinal hernia', false, 'Ruled out because inguinal hernias arise above and medial to the pubic tubercle, not below and lateral to it.', 1),
('c8000000-0000-0000-0000-000000000024', 'B', 'Inguinal lymphadenopathy', false, 'Ruled out because lymphadenopathy would not typically be described as partially reducible with this anatomical relationship to the pubic tubercle.', 2),
('c8000000-0000-0000-0000-000000000024', 'C', 'Femoral hernia', true, 'Correct. A groin lump below and lateral to the pubic tubercle, arising through the femoral canal, is a femoral hernia; these are more common in women and carry a higher strangulation risk than inguinal hernias.', 3),
('c8000000-0000-0000-0000-000000000024', 'D', 'Saphena varix', false, 'Ruled out because a saphena varix is a soft, compressible swelling at the saphenofemoral junction that disappears on lying flat and has a palpable thrill on coughing, rather than being firm and tender like this.', 4),
('c8000000-0000-0000-0000-000000000024', 'E', 'Psoas abscess', false, 'Ruled out because a psoas abscess typically presents with systemic illness and a swelling associated with hip flexion pain, not this localised groin lump pattern.', 5),
('c8000000-0000-0000-0000-000000000025', 'A', 'Emergency surgical repair today', false, 'Ruled out because there are no signs of incarceration or strangulation; this can be managed electively.', 1),
('c8000000-0000-0000-0000-000000000025', 'B', 'Reassurance only, as umbilical hernias in adults always resolve spontaneously without treatment', false, 'Ruled out because, unlike in infants, umbilical hernias in adults do not spontaneously close and generally require surgical repair.', 2),
('c8000000-0000-0000-0000-000000000025', 'C', 'A truss as definitive curative treatment', false, 'Ruled out because a truss does not cure a hernia and is not considered definitive treatment.', 3),
('c8000000-0000-0000-0000-000000000025', 'D', 'Elective surgical repair, with consideration of weight loss optimisation beforehand', true, 'Correct. Unlike umbilical hernias in infants, adult umbilical hernias do not resolve spontaneously; elective repair is appropriate, ideally after optimising modifiable risk factors such as weight.', 4),
('c8000000-0000-0000-0000-000000000025', 'E', 'No intervention, as umbilical hernias in adults never require surgery', false, 'Ruled out because symptomatic or enlarging umbilical hernias in adults are generally repaired surgically.', 5),
('c8000000-0000-0000-0000-000000000026', 'A', 'Post-operative surgical site infection', true, 'Correct. Post-operative wound infection is one of the strongest risk factors for incisional hernia, as it impairs fascial healing at the incision site.', 1),
('c8000000-0000-0000-0000-000000000026', 'B', 'His sex (male)', false, 'Ruled out because sex is not a major established risk factor for incisional hernia formation, unlike wound infection.', 2),
('c8000000-0000-0000-0000-000000000026', 'C', 'The interval of 8 months since surgery', false, 'Ruled out because the time since surgery is not itself a causative risk factor; it simply reflects when the hernia became apparent.', 3),
('c8000000-0000-0000-0000-000000000026', 'D', 'The midline location of the original incision alone, independent of other factors', false, 'Ruled out because although midline incisions carry higher inherent risk, in this patient the wound infection is the dominant contributing risk factor described.', 4),
('c8000000-0000-0000-0000-000000000026', 'E', 'His age', false, 'Ruled out because age is a weaker contributing factor compared with wound infection, diabetes, and obesity in this scenario.', 5),
('c8000000-0000-0000-0000-000000000027', 'A', 'A gastric outlet mass causing obstruction', false, 'Ruled out because this would indicate a tumour causing gastric outlet obstruction, not a hiatus hernia.', 1),
('c8000000-0000-0000-0000-000000000027', 'B', 'Oesophageal varices at the lower third of the oesophagus', false, 'Ruled out because varices reflect portal hypertension, not a hiatus hernia.', 2),
('c8000000-0000-0000-0000-000000000027', 'C', 'A duodenal ulcer in the first part of the duodenum', false, 'Ruled out because a duodenal ulcer is a separate diagnosis unrelated to displacement of the gastro-oesophageal junction.', 3),
('c8000000-0000-0000-0000-000000000027', 'D', 'Diffuse oesophageal spasm on manometry', false, 'Ruled out because this describes a motility disorder, not the anatomical finding that defines a sliding hiatus hernia.', 4),
('c8000000-0000-0000-0000-000000000027', 'E', 'Displacement of the gastro-oesophageal junction above the diaphragmatic hiatus into the thorax', true, 'Correct. A sliding hiatus hernia, the most common type, involves displacement of the gastro-oesophageal junction and part of the stomach upward through the diaphragmatic hiatus into the thorax.', 5),
('c8000000-0000-0000-0000-000000000028', 'A', 'Immediate emergency laparotomy without attempting reduction', false, 'Ruled out because there are no signs of strangulation, so emergency laparotomy is not the immediate next step; gentle reduction attempt with surgical review is appropriate.', 1),
('c8000000-0000-0000-0000-000000000028', 'B', 'Discharge home with elective outpatient follow-up in 6 weeks', false, 'Ruled out because a newly irreducible hernia requires prompt surgical assessment even if reduced, given the ongoing risk of strangulation.', 2),
('c8000000-0000-0000-0000-000000000028', 'C', 'Attempt gentle manual reduction, with analgesia and after ruling out signs of strangulation, followed by urgent surgical review', true, 'Correct. An irreducible hernia without signs of strangulation may be gently reduced after adequate analgesia, but strangulation must be carefully excluded first, and prompt surgical assessment is still required.', 3),
('c8000000-0000-0000-0000-000000000028', 'D', 'Reassure that irreducibility is not clinically significant and no action is needed', false, 'Ruled out because irreducibility is a significant finding requiring assessment and surgical follow-up.', 4),
('c8000000-0000-0000-0000-000000000028', 'E', 'Apply firm, forceful pressure repeatedly until the hernia reduces, regardless of pain', false, 'Ruled out because forceful reduction risks harm and can mask an underlying strangulation; gentle technique with appropriate safety-netting is required.', 5),
('c8000000-0000-0000-0000-000000000029', 'A', 'Aspirin alone, with no mechanical or heparin-based prophylaxis', false, 'Ruled out because aspirin alone is not the recommended standard prophylaxis strategy for high-risk major orthopaedic surgery when LMWH and mechanical methods are appropriate and not contraindicated.', 1),
('c8000000-0000-0000-0000-000000000029', 'B', 'Mechanical prophylaxis (e.g. intermittent pneumatic compression) plus low molecular weight heparin, continued for an extended period post-operatively', true, 'Correct. Major orthopaedic surgery carries a particularly high VTE risk, and combined mechanical and pharmacological prophylaxis (typically LMWH) is recommended, often continued for an extended period post-operatively.', 2),
('c8000000-0000-0000-0000-000000000029', 'C', 'No prophylaxis needed, as elective orthopaedic surgery carries minimal VTE risk', false, 'Ruled out because major orthopaedic surgery, such as hip replacement, carries a high VTE risk and requires active prophylaxis.', 3),
('c8000000-0000-0000-0000-000000000029', 'D', 'Unfractionated heparin infusion only, with no mechanical prophylaxis', false, 'Ruled out because this is not the standard combined approach recommended for high-risk patients, and omits mechanical prophylaxis.', 4),
('c8000000-0000-0000-0000-000000000029', 'E', 'Full-dose therapeutic anticoagulation started immediately post-operatively', false, 'Ruled out because prophylactic-dose (not therapeutic/treatment-dose) anticoagulation is used for VTE prevention in patients without an established VTE.', 5),
('c8000000-0000-0000-0000-000000000030', 'A', 'Atelectasis', false, 'Ruled out because atelectasis typically causes fever in the first 1-2 post-operative days and would not explain feculent drain output.', 1),
('c8000000-0000-0000-0000-000000000030', 'B', 'Urinary tract infection from a post-op catheter', false, 'Ruled out because UTI typically presents around day 3-5 with urinary symptoms, and does not explain feculent discharge from an abdominal drain.', 2),
('c8000000-0000-0000-0000-000000000030', 'C', 'Wound cellulitis alone', false, 'Ruled out because wound cellulitis typically presents around day 5-7 with localised wound erythema, not feculent discharge from a drain.', 3),
('c8000000-0000-0000-0000-000000000030', 'D', 'Anastomotic leak', true, 'Correct. Feculent discharge from a drain in a patient who has had bowel surgery, with new fever, tachycardia, and abdominal pain around day 5-7, is a red flag for anastomotic leak.', 4),
('c8000000-0000-0000-0000-000000000030', 'E', 'Deep vein thrombosis', false, 'Ruled out because DVT typically presents later (day 7 onwards) with unilateral leg swelling and pain, and does not explain feculent drain discharge.', 5),
('c8000000-0000-0000-0000-000000000031', 'A', 'Cover the wound with saline-soaked sterile dressings, keep the patient nil by mouth, and arrange urgent surgical review for likely re-closure in theatre', true, 'Correct. Full wound (fascial) dehiscence with exposed viscera is a surgical emergency: cover with saline-soaked gauze, keep the patient nil by mouth, provide analgesia, and arrange urgent return to theatre.', 1),
('c8000000-0000-0000-0000-000000000031', 'B', 'Apply a simple dry dressing and review in the outpatient clinic in one week', false, 'Ruled out because exposed bowel through a dehisced wound is a surgical emergency requiring immediate management, not deferred outpatient review.', 2),
('c8000000-0000-0000-0000-000000000031', 'C', 'Reassure and continue current management with no change', false, 'Ruled out because this is a surgical emergency requiring urgent intervention, not observation alone.', 3),
('c8000000-0000-0000-0000-000000000031', 'D', 'Attempt to manually push the exposed bowel back through the wound at the bedside without surgical involvement', false, 'Ruled out because manipulating exposed bowel at the bedside risks contamination and injury; this should be managed by the surgical team in theatre.', 4),
('c8000000-0000-0000-0000-000000000031', 'E', 'Discharge home with community nurse wound review', false, 'Ruled out because this patient requires immediate inpatient surgical management, not discharge.', 5),
('c8000000-0000-0000-0000-000000000032', 'A', 'Mechanical small bowel obstruction due to early adhesions', false, 'Ruled out because mechanical obstruction more often shows dilated bowel proximal to a clear transition point and colicky pain, rather than uniform distension without a transition point.', 1),
('c8000000-0000-0000-0000-000000000032', 'B', 'Anastomotic leak', false, 'Ruled out because there is no fever, tachycardia, or peritonism to suggest a leak, and the presentation is consistent with simple ileus.', 2),
('c8000000-0000-0000-0000-000000000032', 'C', 'Sigmoid volvulus', false, 'Ruled out because volvulus produces a specific dilated colonic loop pattern, not uniform distension of both small and large bowel.', 3),
('c8000000-0000-0000-0000-000000000032', 'D', 'Post-operative (paralytic) ileus', true, 'Correct. Distension with delayed return of bowel function and diffuse (non-colicky) discomfort in the early post-operative period, with uniform gaseous distension of both small and large bowel, is typical of post-operative ileus.', 4),
('c8000000-0000-0000-0000-000000000032', 'E', 'Acute mesenteric ischaemia', false, 'Ruled out because there is no severe pain out of proportion to examination or raised lactate described, and observations are stable.', 5),
('c8000000-0000-0000-0000-000000000033', 'A', 'Diabetes insipidus', false, 'Ruled out because diabetes insipidus causes excessive dilute urine output and would tend to cause hypernatraemia, not hyponatraemia, and is not the expected post-operative physiological response.', 1),
('c8000000-0000-0000-0000-000000000033', 'B', 'Dilutional hyponatraemia from excessive hypotonic (dextrose-containing) fluid administration in the context of post-operative antidiuretic hormone release', true, 'Correct. Surgical stress increases ADH secretion, promoting water retention; giving excess hypotonic fluid such as 5% dextrose in this setting risks dilutional hyponatraemia.', 2),
('c8000000-0000-0000-0000-000000000033', 'C', 'Addisonian crisis', false, 'Ruled out because there is no history or examination findings suggesting adrenal insufficiency, and the clinical context points to excess hypotonic fluid administration.', 3),
('c8000000-0000-0000-0000-000000000033', 'D', 'Excessive insensible fluid losses', false, 'Ruled out because insensible losses would tend to cause fluid depletion and relative concentration, not dilutional hyponatraemia from excess hypotonic fluid.', 4),
('c8000000-0000-0000-0000-000000000033', 'E', 'Primary polydipsia', false, 'Ruled out because the patient is described as tolerating oral fluids poorly, so excess self-directed water intake is not the explanation here.', 5),
('c8000000-0000-0000-0000-000000000034', 'A', 'Continue warfarin unchanged right up to and including the day of surgery', false, 'Ruled out because continuing warfarin up to surgery would leave the patient anticoagulated and at high risk of perioperative bleeding.', 1),
('c8000000-0000-0000-0000-000000000034', 'B', 'Stop warfarin only on the morning of surgery', false, $x$Ruled out because warfarin's long half-life means stopping it only on the morning of surgery would not allow the INR to normalise in time.$x$, 2),
('c8000000-0000-0000-0000-000000000034', 'C', 'Double the warfarin dose in the days before surgery', false, 'Ruled out because increasing the dose would worsen anticoagulation and bleeding risk before surgery, which is the opposite of what is required.', 3),
('c8000000-0000-0000-0000-000000000034', 'D', 'Switch to aspirin alone with no other bridging measure required', false, 'Ruled out because this is not the standard approach to peri-operative anticoagulation management for warfarin; decisions on interruption and any bridging require an individualised plan, not a routine switch to aspirin.', 4),
('c8000000-0000-0000-0000-000000000034', 'E', 'Stop warfarin approximately 5 days before surgery and check the INR the day before/of surgery to confirm it has normalised', true, 'Correct. Warfarin is typically stopped around 5 days before elective surgery given its long half-life, with the INR checked shortly before the procedure to confirm normalisation.', 5),
('c8000000-0000-0000-0000-000000000035', 'A', 'Stop all food and fluids, including water, from midnight the night before regardless of surgery time', false, 'Ruled out because prolonged, unnecessary fasting from midnight regardless of surgery time is now discouraged and offers no additional safety benefit.', 1),
('c8000000-0000-0000-0000-000000000035', 'B', 'Continue eating a light meal up until 1 hour before surgery', false, 'Ruled out because solid food should be stopped 6 hours before surgery to reduce aspiration risk, not continued up to 1 hour before.', 2),
('c8000000-0000-0000-0000-000000000035', 'C', 'Stop eating solid food 6 hours before surgery, but clear fluids may be taken up to 2 hours before surgery', true, $x$Correct. Standard pre-operative fasting guidance is '6 and 2': solid food and milk-containing drinks stopped 6 hours before surgery, and clear fluids permitted up to 2 hours before surgery.$x$, 3),
('c8000000-0000-0000-0000-000000000035', 'D', 'No fasting is required before general anaesthesia', false, 'Ruled out because fasting is required before general anaesthesia to reduce the risk of pulmonary aspiration of gastric contents.', 4),
('c8000000-0000-0000-0000-000000000035', 'E', 'Stop clear fluids 6 hours before surgery but solid food may be eaten up to 2 hours before', false, 'Ruled out because this reverses the correct guidance; solid food is stopped earlier (6 hours) while clear fluids are permitted later (up to 2 hours before).', 5),
('c8000000-0000-0000-0000-000000000036', 'A', 'Conservative management with outpatient elective cholecystectomy in 6 months', false, 'Ruled out because delayed surgery at 6 months is an older approach; current evidence favours early cholecystectomy within the same admission where possible.', 1),
('c8000000-0000-0000-0000-000000000036', 'B', 'Immediate ERCP', false, 'Ruled out because ERCP is reserved for cases with evidence of common bile duct obstruction or ascending cholangitis, not straightforward cholecystitis.', 2),
('c8000000-0000-0000-0000-000000000036', 'C', 'Discharge with oral antibiotics only and no surgical follow-up', false, 'Ruled out because acute cholecystitis requires inpatient management and surgical follow-up for definitive treatment, not discharge with oral antibiotics alone.', 3),
('c8000000-0000-0000-0000-000000000036', 'D', 'Ursodeoxycholic acid therapy alone to dissolve the gallstones', false, 'Ruled out because this is not an appropriate treatment for acute cholecystitis and does not address the acute inflammatory process.', 4),
('c8000000-0000-0000-0000-000000000036', 'E', 'IV fluids, analgesia, IV antibiotics, and early (within 1 week) laparoscopic cholecystectomy', true, $x$Correct. A positive Murphy's sign with ultrasound evidence of gallbladder wall thickening/pericholecystic fluid confirms acute cholecystitis; current best practice favours early laparoscopic cholecystectomy alongside IV fluids, analgesia, and antibiotics.$x$, 5),
('c8000000-0000-0000-0000-000000000037', 'A', 'Immediate emergency cholecystectomy', false, 'Ruled out because there are no features of cholecystitis, cholangitis, or another emergency here; this can be managed electively.', 1),
('c8000000-0000-0000-0000-000000000037', 'B', 'Advise dietary modification and refer for elective laparoscopic cholecystectomy', true, 'Correct. This is biliary colic from symptomatic gallstones; elective laparoscopic cholecystectomy is recommended to prevent recurrent symptoms and complications.', 2),
('c8000000-0000-0000-0000-000000000037', 'C', 'IV antibiotics as an inpatient', false, 'Ruled out because there is no evidence of infection/inflammation (normal observations, normal gallbladder wall) to warrant antibiotics or admission.', 3),
('c8000000-0000-0000-0000-000000000037', 'D', 'Reassure that no further action is needed as the stones are asymptomatic', false, 'Ruled out because these gallstones are causing symptomatic biliary colic, not incidental asymptomatic stones.', 4),
('c8000000-0000-0000-0000-000000000037', 'E', 'ERCP to remove the gallstones from the gallbladder', false, 'Ruled out because ERCP is used to clear stones from the common bile duct, not to remove stones from within the gallbladder itself; cholecystectomy is the definitive treatment here.', 5),
('c8000000-0000-0000-0000-000000000038', 'A', 'Acute cholecystitis, supported by fever and right upper quadrant pain alone', false, 'Ruled out because cholecystitis does not typically cause obstructive jaundice with a raised bilirubin, ALP, and GGT as seen here.', 1),
('c8000000-0000-0000-0000-000000000038', 'B', 'Acute pancreatitis, supported by epigastric pain and vomiting', false, 'Ruled out because the clinical picture of fever, jaundice, and obstructive liver function tests fits cholangitis, not pancreatitis, and there is no mention of epigastric pain radiating to the back.', 2),
('c8000000-0000-0000-0000-000000000038', 'C', $x$Ascending cholangitis, supported by fever, jaundice, and right upper quadrant pain (Charcot's triad)$x$, true, $x$Correct. Charcot's triad (fever, jaundice, right upper quadrant pain) is classically associated with ascending cholangitis due to biliary obstruction and infection, requiring urgent resuscitation and biliary decompression.$x$, 3),
('c8000000-0000-0000-0000-000000000038', 'D', 'Viral hepatitis, supported by jaundice and malaise', false, 'Ruled out because the obstructive pattern of liver function tests and high fever with rigors point to a biliary/obstructive infective process rather than a primarily hepatocellular viral illness.', 4),
('c8000000-0000-0000-0000-000000000038', 'E', 'Budd-Chiari syndrome, supported by ascites and hepatomegaly', false, 'Ruled out because there is no mention of ascites or hepatomegaly, and this presentation fits an infective biliary obstruction rather than hepatic venous outflow obstruction.', 5),
('c8000000-0000-0000-0000-000000000039', 'A', 'Trial of a proton pump inhibitor for 8 weeks before considering referral', false, 'Ruled out because an empirical PPI trial risks delaying cancer diagnosis when alarm features (progressive dysphagia, weight loss) are present.', 1),
('c8000000-0000-0000-0000-000000000039', 'B', 'Reassure that this is likely a benign oesophageal stricture and review in 3 months', false, 'Ruled out because this assumption risks missing a malignant cause, which must be excluded urgently.', 2),
('c8000000-0000-0000-0000-000000000039', 'C', 'Arrange a barium swallow only, with no endoscopy required', false, 'Ruled out because endoscopy allows both diagnosis and tissue biopsy, and is required rather than barium swallow alone when malignancy is suspected.', 3),
('c8000000-0000-0000-0000-000000000039', 'D', 'Urgent (2-week wait) referral for upper GI endoscopy', true, 'Correct. Progressive dysphagia (solids to liquids) combined with weight loss in an older patient is a red-flag combination requiring urgent endoscopy to exclude oesophageal malignancy.', 4),
('c8000000-0000-0000-0000-000000000039', 'E', 'Refer to speech and language therapy for swallowing assessment first', false, 'Ruled out because this delays urgent investigation for a structural/malignant cause, which must be prioritised first.', 5),
('c8000000-0000-0000-0000-000000000040', 'A', 'Continue PPI therapy and arrange endoscopic surveillance/treatment at an interval appropriate for low-grade dysplasia', true, $x$Correct. The grade of dysplasia in Barrett's oesophagus determines the surveillance/treatment strategy; low-grade dysplasia warrants closer endoscopic surveillance (with endoscopic therapy considered), alongside continued PPI therapy.$x$, 1),
('c8000000-0000-0000-0000-000000000040', 'B', $x$Discharge with no further follow-up required, as Barrett's oesophagus is a benign, self-limiting condition$x$, false, $x$Ruled out because Barrett's oesophagus is a premalignant condition requiring ongoing surveillance, particularly once dysplasia is identified.$x$, 2),
('c8000000-0000-0000-0000-000000000040', 'C', 'Arrange immediate oesophagectomy', false, 'Ruled out because oesophagectomy is not indicated for low-grade dysplasia; this is managed with surveillance or endoscopic therapy, with surgery reserved for more advanced disease.', 3),
('c8000000-0000-0000-0000-000000000040', 'D', $x$Stop PPI therapy, as it is no longer needed once Barrett's is diagnosed$x$, false, $x$Ruled out because long-term PPI therapy is continued to control reflux and is not stopped simply because Barrett's oesophagus has been diagnosed.$x$, 4),
('c8000000-0000-0000-0000-000000000040', 'E', 'Arrange faecal occult blood testing as the primary surveillance method', false, $x$Ruled out because surveillance of Barrett's oesophagus is performed with endoscopy and biopsy, not faecal occult blood testing.$x$, 5),
('c8000000-0000-0000-0000-000000000041', 'A', 'Immediate oral PPI therapy alone, with endoscopy deferred to the next routine list', false, 'Ruled out because a major, haemodynamically significant bleed requires urgent resuscitation and endoscopy, not oral PPI alone with deferred endoscopy.', 1),
('c8000000-0000-0000-0000-000000000041', 'B', 'Discharge with outpatient gastroenterology follow-up', false, 'Ruled out because this patient is haemodynamically unstable with a major GI bleed and requires immediate inpatient resuscitation, not discharge.', 2),
('c8000000-0000-0000-0000-000000000041', 'C', 'Insertion of a nasogastric tube for feeding, with no further intervention', false, 'Ruled out because this does not address the need for urgent resuscitation and endoscopic control of bleeding.', 3),
('c8000000-0000-0000-0000-000000000041', 'D', 'Strict bed rest and observation only, without resuscitation', false, 'Ruled out because this patient is hypotensive and tachycardic from major haemorrhage and requires active resuscitation, not observation alone.', 4),
('c8000000-0000-0000-0000-000000000041', 'E', 'Urgent resuscitation with IV fluids/blood products, correction of coagulopathy, and urgent endoscopy after starting terlipressin and antibiotics for suspected variceal bleed', true, 'Correct. In a patient with known liver disease and a major upper GI bleed, variceal haemorrhage should be assumed until proven otherwise; terlipressin and prophylactic antibiotics should be started promptly alongside resuscitation, pending urgent endoscopy.', 5),
('c8000000-0000-0000-0000-000000000042', 'A', 'Reassurance and dietary advice, with review in 3 months', false, 'Ruled out because red-flag features here require urgent investigation, not reassurance and delayed review.', 1),
('c8000000-0000-0000-0000-000000000042', 'B', 'Start empirical Helicobacter pylori eradication therapy without further investigation', false, 'Ruled out because empirical treatment should not be started before excluding malignancy when alarm features are present.', 2),
('c8000000-0000-0000-0000-000000000042', 'C', 'Urgent (2-week wait) referral for upper GI endoscopy', true, 'Correct. New dyspeptic symptoms with weight loss, iron-deficiency anaemia, and evidence suggestive of GI bleeding (dark stools) in an older adult are red-flag features requiring urgent endoscopy to exclude gastric cancer.', 3),
('c8000000-0000-0000-0000-000000000042', 'D', 'Faecal immunochemical test (FIT) as the definitive investigation', false, 'Ruled out because FIT is used in specific lower GI cancer pathways, not as the definitive investigation for suspected upper GI malignancy with these symptoms.', 4),
('c8000000-0000-0000-0000-000000000042', 'E', 'Refer routinely to dietetics for weight loss management', false, 'Ruled out because this does not address the need to urgently exclude an underlying malignant cause of his symptoms.', 5),
('c8000000-0000-0000-0000-000000000043', 'A', 'Elective outpatient vascular referral in 2 weeks', false, 'Ruled out because acute limb ischaemia with sensorimotor deficit is a limb-threatening emergency requiring immediate, not elective, referral.', 1),
('c8000000-0000-0000-0000-000000000043', 'B', 'Urgent vascular surgical referral for emergency revascularisation (e.g. embolectomy), with IV heparin started while awaiting intervention', true, 'Correct. Sudden pallor, coldness, pulselessness, and sensorimotor deficit indicate acute limb-threatening ischaemia; IV heparin should be started promptly with urgent vascular referral for emergency revascularisation.', 2),
('c8000000-0000-0000-0000-000000000043', 'C', 'Compression bandaging and leg elevation only', false, 'Ruled out because this does not address the underlying arterial occlusion and delays urgent revascularisation.', 3),
('c8000000-0000-0000-0000-000000000043', 'D', 'Oral aspirin alone, with no further intervention', false, 'Ruled out because aspirin alone does not treat an acute arterial occlusion causing limb-threatening ischaemia.', 4),
('c8000000-0000-0000-0000-000000000043', 'E', 'Reassure and review again in 24 hours', false, 'Ruled out because a threatened limb with sensory and motor deficit needs intervention within hours, not delayed review.', 5),
('c8000000-0000-0000-0000-000000000044', 'A', 'Arrange an outpatient CT abdomen in the next few days to confirm the diagnosis before any treatment', false, 'Ruled out because this presentation is a life-threatening emergency requiring immediate action, not deferred outpatient imaging.', 1),
('c8000000-0000-0000-0000-000000000044', 'B', 'Aggressive fluid resuscitation to restore a normal blood pressure before any surgical involvement', false, $x$Ruled out because 'permissive hypotension' rather than full normalisation of blood pressure is used to avoid dislodging a stabilising clot and worsening haemorrhage before definitive repair.$x$, 2),
('c8000000-0000-0000-0000-000000000044', 'C', 'Discharge with analgesia and GP follow-up', false, 'Ruled out because this patient has a life-threatening surgical emergency and must not be discharged.', 3),
('c8000000-0000-0000-0000-000000000044', 'D', 'Urgent resuscitation with permissive hypotension, immediate vascular surgery referral, and transfer for emergency repair', true, 'Correct. Sudden severe abdominal/back pain with hypotension and a pulsatile abdominal mass is the classic triad of a ruptured abdominal aortic aneurysm; management is permissive hypotension resuscitation with immediate transfer for emergency repair.', 4),
('c8000000-0000-0000-0000-000000000044', 'E', 'Reassure that this is likely renal colic and start alpha-blocker therapy', false, 'Ruled out because the pulsatile expansile mass with hypotension and collapse is characteristic of ruptured AAA, not renal colic.', 5),
('c8000000-0000-0000-0000-000000000045', 'A', 'Referral into the surveillance programme for annual ultrasound monitoring, as this is a small aneurysm', true, 'Correct. Small aneurysms detected on screening are managed with regular ultrasound surveillance and cardiovascular risk factor modification, with the interval shortening as the aneurysm enlarges.', 1),
('c8000000-0000-0000-0000-000000000045', 'B', 'Immediate referral for elective open or endovascular aneurysm repair', false, 'Ruled out because elective repair is reserved for larger, rapidly expanding, or symptomatic aneurysms, not a small aneurysm of this size detected on screening.', 2),
('c8000000-0000-0000-0000-000000000045', 'C', 'Discharge with no further follow-up required', false, 'Ruled out because an aneurysm of this size still requires ongoing surveillance to monitor for growth, not discharge with no follow-up.', 3),
('c8000000-0000-0000-0000-000000000045', 'D', 'CT angiography every 6 months indefinitely', false, 'Ruled out because ultrasound, not CT angiography, is the standard surveillance modality used at intervals determined by aneurysm size.', 4),
('c8000000-0000-0000-0000-000000000045', 'E', 'Emergency hospital admission for observation', false, 'Ruled out because this is an asymptomatic, incidentally detected small aneurysm and does not require emergency admission.', 5),
('c8000000-0000-0000-0000-000000000046', 'A', 'Venous duplex ultrasound', false, 'Ruled out because this assesses venous, not arterial, pathology, and would not address his claudication symptoms.', 1),
('c8000000-0000-0000-0000-000000000046', 'B', 'D-dimer', false, 'Ruled out because D-dimer is used in the work-up of suspected VTE, not for assessing peripheral arterial disease severity.', 2),
('c8000000-0000-0000-0000-000000000046', 'C', 'Ankle-brachial pressure index (ABPI)', true, 'Correct. Intermittent claudication is the classic symptom of peripheral arterial disease, and the ankle-brachial pressure index is the simple, non-invasive first-line test to confirm and grade its severity.', 3),
('c8000000-0000-0000-0000-000000000046', 'D', 'CT pulmonary angiogram', false, 'Ruled out because this investigates suspected pulmonary embolism, which is not relevant to this presentation.', 4),
('c8000000-0000-0000-0000-000000000046', 'E', 'Ambulatory venous pressure measurement', false, 'Ruled out because this assesses venous insufficiency, not arterial disease severity.', 5),
('c8000000-0000-0000-0000-000000000047', 'A', 'Reassurance only, as his symptoms have fully resolved', false, 'Ruled out because full symptom resolution does not remove the ongoing high risk of subsequent stroke from significant symptomatic carotid stenosis.', 1),
('c8000000-0000-0000-0000-000000000047', 'B', 'Anticoagulation with warfarin as the definitive treatment', false, 'Ruled out because anticoagulation is not the standard definitive treatment for symptomatic carotid stenosis; antiplatelet therapy and carotid intervention are used instead.', 2),
('c8000000-0000-0000-0000-000000000047', 'C', 'Watchful waiting with repeat duplex ultrasound in 12 months', false, 'Ruled out because significant symptomatic stenosis requires prompt intervention, not a 12-month period of watchful waiting given the high early recurrent stroke risk.', 3),
('c8000000-0000-0000-0000-000000000047', 'D', 'Urgent referral for carotid endarterectomy, alongside best medical therapy (antiplatelet, statin, blood pressure control)', true, 'Correct. Significant symptomatic carotid stenosis (typically 70% or more) is an indication for prompt carotid endarterectomy to reduce future stroke risk, alongside best medical therapy.', 4),
('c8000000-0000-0000-0000-000000000047', 'E', 'Referral for carotid artery stenting only if he develops a further event', false, 'Ruled out because intervention should be arranged promptly after this qualifying event, not deferred until a further event occurs.', 5),
('c8000000-0000-0000-0000-000000000048', 'A', 'Proximal leg vein ultrasound (Doppler)', true, 'Correct. Proximal leg vein ultrasound (compression Doppler) is the definitive first-line imaging investigation when a Wells score indicates DVT is clinically likely.', 1),
('c8000000-0000-0000-0000-000000000048', 'B', 'D-dimer testing alone, with no further imaging required', false, 'Ruled out because when DVT is clinically likely, ultrasound should be arranged directly rather than relying on D-dimer alone; D-dimer-first pathways are used when DVT is considered unlikely.', 2),
('c8000000-0000-0000-0000-000000000048', 'C', 'CT pulmonary angiogram', false, 'Ruled out because this investigates for pulmonary embolism, not to confirm a suspected DVT in the leg.', 3),
('c8000000-0000-0000-0000-000000000048', 'D', 'Chest X-ray', false, 'Ruled out because this would not assess the suspected leg DVT and is not the appropriate next investigation here.', 4),
('c8000000-0000-0000-0000-000000000048', 'E', 'Venography as first-line investigation', false, 'Ruled out because venography is invasive and not first-line; ultrasound is the standard first-line imaging test.', 5),
('c8000000-0000-0000-0000-000000000049', 'A', 'Mild aching relieved by leg elevation at the end of the day', false, 'Ruled out because mild symptoms relieved by simple measures like elevation are consistent with uncomplicated varicose veins managed conservatively.', 1),
('c8000000-0000-0000-0000-000000000049', 'B', 'Development of skin changes such as lipodermatosclerosis or venous ulceration', true, 'Correct. Skin changes such as lipodermatosclerosis or venous ulceration reflect more advanced chronic venous insufficiency and are red-flag features warranting referral to vascular services.', 2),
('c8000000-0000-0000-0000-000000000049', 'C', 'Cosmetic appearance alone, with no other symptoms', false, 'Ruled out because cosmetic concerns alone, without functional symptoms or skin changes, do not represent a red-flag indication for urgent vascular referral.', 3),
('c8000000-0000-0000-0000-000000000049', 'D', 'Symptoms that have been stable for several years', false, 'Ruled out because long-standing, stable, mild symptoms do not in themselves indicate a need for referral.', 4),
('c8000000-0000-0000-0000-000000000049', 'E', 'Visible tortuosity without other symptoms', false, 'Ruled out because visible tortuosity alone, without skin changes, ulceration, or significant symptoms, does not mandate referral.', 5),
('c8000000-0000-0000-0000-000000000050', 'A', 'Venous ulcer', false, 'Ruled out because venous ulcers are typically less painful, occur over the medial malleolus, and improve with elevation rather than dependency.', 1),
('c8000000-0000-0000-0000-000000000050', 'B', 'Neuropathic (pressure) ulcer', false, 'Ruled out because neuropathic ulcers are typically painless (due to sensory loss) and occur at pressure points from unnoticed trauma, unlike this painful ulcer with pain relieved by dependency.', 2),
('c8000000-0000-0000-0000-000000000050', 'C', 'Pyoderma gangrenosum', false, 'Ruled out because this is a rare inflammatory condition with a violaceous, undermined border, not explained by pulse loss and dependency-related pain relief.', 3),
('c8000000-0000-0000-0000-000000000050', 'D', 'Squamous cell carcinoma', false, 'Ruled out because this presentation with absent pulses and pain relieved by dependency is characteristic of arterial disease, not a primary skin malignancy.', 4),
('c8000000-0000-0000-0000-000000000050', 'E', 'Arterial ulcer', true, $x$Correct. A painful, 'punched-out' ulcer at a distal pressure point with a pale/necrotic base, absent pulses, and pain relieved by dependency (hanging the leg down) is characteristic of an arterial ulcer.$x$, 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('c8000000-0000-0000-0000-000000000001', $x$Migratory periumbilical pain localising to the right iliac fossa (McBurney's point) is the classic history of acute appendicitis.$x$, 1),
('c8000000-0000-0000-0000-000000000001', $x$Rebound tenderness, percussion tenderness, and a positive Rovsing's sign indicate localised peritonism requiring urgent surgical assessment.$x$, 2),
('c8000000-0000-0000-0000-000000000001', 'Pregnancy test and urinalysis should be checked in all women of childbearing age to exclude ectopic pregnancy and UTI as differentials.', 3),
('c8000000-0000-0000-0000-000000000002', 'Sudden severe abdominal pain with a rigid, guarded abdomen and absent bowel sounds suggests perforation with generalised peritonitis.', 1),
('c8000000-0000-0000-0000-000000000002', 'NSAID use is a major risk factor for peptic ulcer disease and perforation.', 2),
('c8000000-0000-0000-0000-000000000002', 'Free air under the diaphragm on an erect chest X-ray is the classic sign of pneumoperitoneum from a perforated viscus; management is resuscitation (IV fluids, analgesia, broad-spectrum antibiotics) followed by urgent surgery.', 3),
('c8000000-0000-0000-0000-000000000003', 'Adhesions from previous abdominal/pelvic surgery are the most common cause of small bowel obstruction in adults.', 1),
('c8000000-0000-0000-0000-000000000003', 'Colicky pain, distension, vomiting, and absolute constipation (no flatus or stool) are the cardinal features of bowel obstruction.', 2),
('c8000000-0000-0000-0000-000000000003', $x$Initial management of uncomplicated small bowel obstruction is conservative ('drip and suck': NBM, IV fluids, NG decompression) with surgery reserved for failure to resolve or signs of strangulation/ischaemia (peritonism, tachycardia, rising lactate).$x$, 3),
('c8000000-0000-0000-0000-000000000004', 'Severe abdominal pain that is disproportionate to relatively unremarkable examination findings is a classic feature of acute mesenteric ischaemia.', 1),
('c8000000-0000-0000-0000-000000000004', 'Atrial fibrillation is a major risk factor for embolic occlusion of the superior mesenteric artery.', 2),
('c8000000-0000-0000-0000-000000000004', 'A markedly raised lactate reflects bowel ischaemia and should prompt urgent CT angiography and surgical review, as mortality is high and diagnosis is easily delayed.', 3),
('c8000000-0000-0000-0000-000000000005', 'Generalised peritonism with septic shock in a patient with known diverticular disease raises suspicion of perforated diverticulitis.', 1),
('c8000000-0000-0000-0000-000000000005', 'Sepsis six (cultures, lactate, IV fluids, oxygen, antibiotics, urine output monitoring) must be started immediately in any patient with suspected sepsis, alongside urgent senior surgical review.', 2),
('c8000000-0000-0000-0000-000000000005', 'Colonoscopy is contraindicated in suspected perforation due to the risk of insufflating air through a perforation and worsening peritoneal contamination; CT is the imaging of choice.', 3),
('c8000000-0000-0000-0000-000000000006', 'Gallstones and alcohol are the two most common causes of acute pancreatitis; a markedly raised amylase (or lipase) supports the diagnosis in the correct clinical context.', 1),
('c8000000-0000-0000-0000-000000000006', 'Initial management is supportive: aggressive IV fluid resuscitation, analgesia, and close monitoring, with severity stratified using a validated score (e.g. Glasgow-Imrie, APACHE II).', 2),
('c8000000-0000-0000-0000-000000000006', 'Antibiotics are not given routinely in acute pancreatitis unless there is evidence of infected necrosis or associated cholangitis; ERCP is reserved for cases with ongoing biliary obstruction or cholangitis.', 3),
('c8000000-0000-0000-0000-000000000007', $x$Elderly, immobile patients with chronic constipation (e.g. Parkinson's disease, care-home residents) are at higher risk of sigmoid volvulus.$x$, 1),
('c8000000-0000-0000-0000-000000000007', $x$The 'coffee bean' sign on abdominal X-ray represents a dilated, twisted loop of sigmoid colon.$x$, 2),
('c8000000-0000-0000-0000-000000000007', 'First-line management of uncomplicated sigmoid volvulus (no peritonism or perforation) is endoscopic (sigmoidoscopic) decompression with flatus tube placement; surgery is reserved for failed decompression, recurrence, or signs of ischaemia/perforation.', 3),
('c8000000-0000-0000-0000-000000000008', 'A discrete, hard, irregular breast lump in a woman over 30, especially with skin tethering, is a red flag requiring urgent 2-week-wait referral.', 1),
('c8000000-0000-0000-0000-000000000008', 'Triple assessment (clinical examination, imaging - mammography and/or ultrasound, and core biopsy/FNA) is the standard pathway for evaluating a suspicious breast lump.', 2),
('c8000000-0000-0000-0000-000000000008', 'Absence of a palpable axillary lump does not exclude malignancy and should not delay urgent referral.', 3),
('c8000000-0000-0000-0000-000000000009', $x$Fibroadenomas are the most common cause of a discrete breast lump in women under 30 and are classically smooth, mobile, and well-circumscribed ('breast mouse').$x$, 1),
('c8000000-0000-0000-0000-000000000009', 'Despite the benign clinical picture, younger patients with a palpable lump should still be referred for triple assessment (usually via ultrasound rather than mammography given breast density) to confirm the diagnosis.', 2),
('c8000000-0000-0000-0000-000000000009', 'Fibroadenomas that are stable, small, and confirmed benign on imaging/core biopsy can usually be managed conservatively with reassurance rather than excision.', 3),
('c8000000-0000-0000-0000-000000000010', 'Lactational mastitis is common, often related to milk stasis or a cracked nipple allowing bacterial entry (typically Staphylococcus aureus).', 1),
('c8000000-0000-0000-0000-000000000010', 'Continued breastfeeding or expressing from the affected side, along with appropriate antibiotics if infection is suspected, is recommended and does not harm the infant.', 2),
('c8000000-0000-0000-0000-000000000010', 'Ultrasound and drainage are reserved for cases where a fluctuant collection (abscess) is suspected or antibiotics fail to resolve the mastitis.', 3),
('c8000000-0000-0000-0000-000000000011', $x$Paget's disease of the nipple presents as a unilateral, eczema-like rash of the nipple/areola that fails to respond to topical treatment - it should never be assumed to be eczema without exclusion of malignancy.$x$, 1),
('c8000000-0000-0000-0000-000000000011', $x$Paget's disease of the nipple is strongly associated with underlying ductal carcinoma in situ or invasive breast cancer, even when no lump is palpable.$x$, 2),
('c8000000-0000-0000-0000-000000000011', 'Biopsy of the nipple skin is required for diagnosis, alongside standard triple assessment (imaging and biopsy) of the underlying breast.', 3),
('c8000000-0000-0000-0000-000000000012', 'Fat necrosis can occur after trauma and clinically (and sometimes radiologically) mimics breast cancer, with a firm, irregular lump and skin tethering/dimpling.', 1),
('c8000000-0000-0000-0000-000000000012', 'A clear history of trauma does not exclude malignancy, and any new discrete breast lump still warrants triple assessment.', 2),
('c8000000-0000-0000-0000-000000000012', 'Definitive diagnosis of fat necrosis requires imaging and often core biopsy, as it cannot be reliably distinguished from carcinoma on clinical grounds alone.', 3),
('c8000000-0000-0000-0000-000000000013', 'Unilateral, spontaneous, blood-stained nipple discharge is a red-flag feature requiring urgent breast clinic referral, even in the absence of a palpable lump.', 1),
('c8000000-0000-0000-0000-000000000013', 'Bilateral, milky, or multi-duct discharge is more typical of benign causes such as duct ectasia or physiological/galactorrhoea-related discharge.', 2),
('c8000000-0000-0000-0000-000000000013', 'Triple assessment (including imaging and cytology of the discharge or ductoscopy/biopsy where indicated) is needed to exclude an underlying intraductal papilloma or carcinoma.', 3),
('c8000000-0000-0000-0000-000000000014', 'Inflammatory breast cancer can mimic mastitis/abscess with erythema, warmth, and skin thickening, but occurs classically in non-lactating (often postmenopausal) women and fails to respond to antibiotics.', 1),
('c8000000-0000-0000-0000-000000000014', $x$Peau d'orange skin change reflects dermal lymphatic obstruction by tumour and, combined with matted axillary lymphadenopathy, is highly suspicious of locally advanced/inflammatory breast cancer.$x$, 2),
('c8000000-0000-0000-0000-000000000014', 'Any breast infection that fails to respond to appropriate antibiotics, especially outside the typical lactational context, requires urgent referral to exclude malignancy rather than repeated antibiotic courses.', 3),
('c8000000-0000-0000-0000-000000000015', 'Rectal bleeding with a change in bowel habit, unintentional weight loss, and iron-deficiency anaemia in a patient over 60 are red-flag features requiring urgent investigation for colorectal cancer.', 1),
('c8000000-0000-0000-0000-000000000015', 'A normal digital rectal examination does not exclude a more proximal colorectal lesion; colonoscopy remains indicated.', 2),
('c8000000-0000-0000-0000-000000000015', 'Iron-deficiency anaemia of unclear cause in an adult, particularly with lower GI symptoms, should prompt urgent colorectal cancer pathway referral rather than empirical treatment.', 3),
('c8000000-0000-0000-0000-000000000016', 'Uncomplicated diverticular disease (diverticulosis) without signs of infection or complication is managed conservatively with dietary fibre and analgesia.', 1),
('c8000000-0000-0000-0000-000000000016', 'Antibiotics and further imaging/intervention are reserved for acute diverticulitis (fever, localised peritonism, raised inflammatory markers) or complications such as abscess, perforation, or fistula.', 2),
('c8000000-0000-0000-0000-000000000016', 'Patients should be given safety-net advice to seek urgent review if they develop fever, worsening pain, or rectal bleeding, which would suggest progression to diverticulitis or a complication.', 3),
('c8000000-0000-0000-0000-000000000017', 'A posterior midline linear tear with a sentinel pile is the classic finding of an anal fissure, most often due to trauma from a hard stool.', 1),
('c8000000-0000-0000-0000-000000000017', 'First-line management is conservative: increasing dietary fibre and fluids, stool softeners/laxatives, and topical GTN or diltiazem to relax the internal anal sphincter and improve blood flow for healing.', 2),
('c8000000-0000-0000-0000-000000000017', 'Surgical options (sphincterotomy) or botulinum toxin are reserved for chronic fissures that fail an adequate trial of conservative and topical treatment.', 3),
('c8000000-0000-0000-0000-000000000018', 'Painless bright red rectal bleeding with a sensation of prolapse that reduces spontaneously is typical of internal haemorrhoids.', 1),
('c8000000-0000-0000-0000-000000000018', 'Conservative measures (fibre, fluids, topical treatments) are first-line, with banding or other outpatient procedures reserved for persistent symptoms.', 2),
('c8000000-0000-0000-0000-000000000018', 'Red-flag features (weight loss, change in stool calibre, anaemia, family history, age-related risk) should always be actively excluded before attributing rectal bleeding to haemorrhoids, especially since colorectal cancer can coexist.', 3),
('c8000000-0000-0000-0000-000000000019', 'Truelove and Witts criteria (stool frequency 6 or more per day with systemic features such as fever, tachycardia, or anaemia) define acute severe ulcerative colitis, which requires hospital admission.', 1),
('c8000000-0000-0000-0000-000000000019', 'IV corticosteroids are first-line for acute severe UC, alongside careful monitoring for toxic megacolon (a life-threatening complication) with serial abdominal examination and imaging.', 2),
('c8000000-0000-0000-0000-000000000019', 'Anti-motility agents (e.g. loperamide) should be avoided in acute severe colitis as they can precipitate toxic megacolon.', 3),
('c8000000-0000-0000-0000-000000000020', $x$Crohn's disease can affect any part of the GI tract (classically terminal ileum/right iliac fossa) and is associated with perianal disease, including fistulae, abscesses, and skin tags, unlike ulcerative colitis.$x$, 1),
('c8000000-0000-0000-0000-000000000020', $x$Weight loss, iron-deficiency anaemia, and a raised CRP reflect chronic inflammation and malabsorption typical of Crohn's disease.$x$, 2),
('c8000000-0000-0000-0000-000000000020', $x$Diarrhoea in Crohn's disease is not always bloody (unlike the bloody diarrhoea typical of ulcerative colitis), and diagnosis requires colonoscopy with biopsy and cross-sectional imaging to define disease extent.$x$, 3),
('c8000000-0000-0000-0000-000000000021', 'Ischaemic colitis typically affects watershed areas of the colon (e.g. splenic flexure, rectosigmoid junction) supplied by low-flow anastomotic circulation between vascular territories.', 1),
('c8000000-0000-0000-0000-000000000021', $x$'Thumbprinting' on abdominal X-ray reflects submucosal oedema/haemorrhage and is characteristic of ischaemic colitis.$x$, 2),
('c8000000-0000-0000-0000-000000000021', 'Most cases of ischaemic colitis are managed conservatively (IV fluids, bowel rest, monitoring) as they are non-gangrenous, but signs of peritonism or clinical deterioration should prompt urgent surgical review for possible transmural infarction.', 3),
('c8000000-0000-0000-0000-000000000022', 'A reducible groin lump that appears on standing/straining and reduces on lying down, situated above and medial to the pubic tubercle, is typical of an inguinal hernia.', 1),
('c8000000-0000-0000-0000-000000000022', 'Symptomatic inguinal hernias are generally managed with elective surgical repair to reduce the risk of complications such as incarceration or strangulation.', 2),
('c8000000-0000-0000-0000-000000000022', 'Trusses are not considered a definitive treatment and are reserved for patients unfit for surgery; they do not prevent complications reliably.', 3),
('c8000000-0000-0000-0000-000000000023', 'A previously reducible hernia that becomes irreducible, tender, and erythematous with systemic signs (fever, tachycardia) suggests strangulation with compromised blood supply to the herniated bowel.', 1),
('c8000000-0000-0000-0000-000000000023', 'Strangulated hernias are a surgical emergency requiring urgent resuscitation and operative intervention to prevent bowel ischaemia/necrosis and perforation.', 2),
('c8000000-0000-0000-0000-000000000023', 'Forceful reduction should not be attempted when strangulation is suspected, as this can reduce non-viable bowel into the abdomen and delay recognition of ischaemia.', 3),
('c8000000-0000-0000-0000-000000000024', 'Femoral hernias occur below and lateral to the pubic tubercle (through the femoral canal), in contrast to inguinal hernias which arise above and medial to it.', 1),
('c8000000-0000-0000-0000-000000000024', 'Femoral hernias are more common in women and carry a higher risk of incarceration and strangulation than inguinal hernias due to the narrow, rigid boundaries of the femoral canal.', 2),
('c8000000-0000-0000-0000-000000000024', 'Because of this elevated strangulation risk, femoral hernias are generally repaired surgically even when asymptomatic or easily reducible, unlike some inguinal hernias which may be managed expectantly if minimally symptomatic.', 3),
('c8000000-0000-0000-0000-000000000025', 'Unlike umbilical hernias in infants, which often close spontaneously by age 2-4, umbilical hernias in adults do not resolve spontaneously and generally require elective surgical repair if symptomatic or enlarging.', 1),
('c8000000-0000-0000-0000-000000000025', 'Obesity is a risk factor for umbilical hernia development and for surgical complications; weight optimisation is often recommended before elective repair where feasible.', 2),
('c8000000-0000-0000-0000-000000000025', 'Elective (rather than emergency) repair is appropriate in the absence of signs of incarceration or strangulation (irreducibility, severe pain, overlying skin changes, systemic upset).', 3),
('c8000000-0000-0000-0000-000000000026', 'Incisional hernias develop through a defect in the fascia at a previous surgical incision site and are more common after emergency surgery, midline incisions, and wound infection/breakdown.', 1),
('c8000000-0000-0000-0000-000000000026', 'Risk factors include obesity, diabetes (impaired wound healing), smoking, and post-operative wound infection or dehiscence.', 2),
('c8000000-0000-0000-0000-000000000026', 'Symptomatic or enlarging incisional hernias are generally managed with elective repair, ideally after optimising modifiable risk factors such as glycaemic control and weight.', 3),
('c8000000-0000-0000-0000-000000000027', 'Sliding hiatus hernia, the most common type, involves displacement of the gastro-oesophageal junction and part of the stomach upward through the diaphragmatic hiatus into the thorax.', 1),
('c8000000-0000-0000-0000-000000000027', 'Hiatus hernia commonly presents with symptoms of gastro-oesophageal reflux (heartburn, regurgitation), particularly worse lying flat or after meals.', 2),
('c8000000-0000-0000-0000-000000000027', 'Management is initially conservative (weight loss, lifestyle modification, PPI therapy), with surgical repair (e.g. fundoplication) reserved for refractory symptoms or complications.', 3),
('c8000000-0000-0000-0000-000000000028', 'An irreducible hernia without signs of strangulation (no severe pain, erythema, or systemic illness) may be gently reduced after adequate analgesia, but this should only be attempted when strangulation has been carefully excluded.', 1),
('c8000000-0000-0000-0000-000000000028', 'All incarcerated hernias, even if successfully reduced, require prompt surgical assessment because of the ongoing risk of strangulation and to plan definitive repair.', 2),
('c8000000-0000-0000-0000-000000000028', 'Forceful reduction attempts risk reducing non-viable or perforated bowel into the abdominal cavity, masking a surgical emergency; gentle technique with appropriate safety-netting is essential.', 3),
('c8000000-0000-0000-0000-000000000029', 'All surgical patients should have a formal VTE risk assessment on admission, balancing thromboembolism risk against bleeding risk.', 1),
('c8000000-0000-0000-0000-000000000029', 'Major orthopaedic surgery (e.g. hip/knee replacement) carries a particularly high VTE risk, and combined mechanical and pharmacological prophylaxis (typically LMWH) is recommended, often continued for several weeks post-operatively.', 2),
('c8000000-0000-0000-0000-000000000029', 'Prophylactic-dose anticoagulation (not therapeutic/treatment dose) is used for VTE prevention in patients without an established VTE.', 3),
('c8000000-0000-0000-0000-000000000030', 'A useful framework for post-operative fever is timing: atelectasis (day 1-2), infections such as UTI or pneumonia (day 3-5), wound infections (day 5-7), and VTE (day 5 onwards, especially after day 7).', 1),
('c8000000-0000-0000-0000-000000000030', 'Feculent or bilious discharge from an abdominal drain in a patient who has had bowel surgery is a red flag for anastomotic leak and requires urgent investigation (e.g. CT with contrast) and senior surgical review.', 2),
('c8000000-0000-0000-0000-000000000030', 'Anastomotic leaks classically present around day 5-7 post-operatively with new fever, tachycardia, abdominal pain, and systemic deterioration, and carry significant morbidity/mortality if not promptly recognised and managed.', 3),
('c8000000-0000-0000-0000-000000000031', $x$'Pink fluid sign' - serosanguinous discharge from a laparotomy wound - is a classic warning sign preceding full wound (fascial) dehiscence/burst abdomen.$x$, 1),
('c8000000-0000-0000-0000-000000000031', 'Risk factors for wound dehiscence include obesity, diabetes (impaired wound healing), emergency surgery, wound infection, and raised intra-abdominal pressure (e.g. coughing, straining).', 2),
('c8000000-0000-0000-0000-000000000031', 'Full dehiscence with exposed viscera is a surgical emergency: cover with saline-soaked gauze, keep the patient nil by mouth, provide analgesia, and arrange urgent return to theatre; the bowel should not be forced back through the defect at the bedside.', 3),
('c8000000-0000-0000-0000-000000000032', 'Post-operative ileus is common in the first few days after abdominal surgery and presents with distension, absent/reduced bowel sounds, and delayed return of flatus/bowel function, typically without colicky pain.', 1),
('c8000000-0000-0000-0000-000000000032', 'Uniform gaseous distension of both small and large bowel on X-ray favours ileus, whereas mechanical obstruction more often shows dilated bowel proximal to a clear transition point.', 2),
('c8000000-0000-0000-0000-000000000032', 'Management of ileus is largely supportive (IV fluids, correcting electrolyte abnormalities, encouraging mobilisation, and excluding mechanical causes), with resolution usually expected within a few days.', 3),
('c8000000-0000-0000-0000-000000000033', 'Surgical stress and pain trigger increased antidiuretic hormone (ADH) secretion, promoting water retention; giving excess hypotonic fluid (such as 5% dextrose) in this setting risks dilutional hyponatraemia.', 1),
('c8000000-0000-0000-0000-000000000033', 'Post-operative fluid prescribing should account for maintenance requirements, ongoing losses, and this physiological ADH response, generally favouring isotonic fluids and avoiding excessive volumes in the first 24-48 hours after surgery.', 2),
('c8000000-0000-0000-0000-000000000033', 'Significant hyponatraemia can cause confusion, seizures, and, if severe or rapidly corrected, cerebral oedema or osmotic demyelination; electrolytes should be monitored closely in post-operative patients receiving IV fluids.', 3),
('c8000000-0000-0000-0000-000000000034', 'Warfarin is typically stopped around 5 days before elective surgery to allow the INR to normalise, given its long half-life, with the INR checked shortly before the procedure.', 1),
('c8000000-0000-0000-0000-000000000034', $x$The decision on whether bridging anticoagulation (e.g. LMWH) is needed during the interruption depends on the patient's underlying thromboembolic risk (e.g. CHA2DS2-VASc score, valve type) balanced against bleeding risk from the planned procedure.$x$, 2),
('c8000000-0000-0000-0000-000000000034', 'Clear, individualised peri-operative anticoagulation plans should be made with input from the prescribing/anticoagulation team, particularly for patients on warfarin or DOACs undergoing surgery.', 3),
('c8000000-0000-0000-0000-000000000035', $x$Standard pre-operative fasting guidance is '6 and 2': solid food and milk-containing drinks stopped 6 hours before surgery, and clear fluids permitted up to 2 hours before surgery.$x$, 1),
('c8000000-0000-0000-0000-000000000035', 'The purpose of fasting is to reduce gastric volume and thus reduce the risk of pulmonary aspiration during induction of general anaesthesia.', 2),
('c8000000-0000-0000-0000-000000000035', 'Prolonged, unnecessary fasting (e.g. from midnight regardless of surgery time) is now discouraged, as it offers no additional safety benefit and can cause patient discomfort, dehydration, and hypoglycaemia.', 3),
('c8000000-0000-0000-0000-000000000036', $x$A positive Murphy's sign with ultrasound evidence of gallbladder wall thickening/pericholecystic fluid in the presence of gallstones confirms acute cholecystitis.$x$, 1),
('c8000000-0000-0000-0000-000000000036', 'Current best practice favours early laparoscopic cholecystectomy (ideally within 1 week of symptom onset) over delayed surgery, alongside IV fluids, analgesia, and antibiotics.', 2),
('c8000000-0000-0000-0000-000000000036', 'ERCP is reserved for cases with evidence of common bile duct obstruction (e.g. deranged liver function tests, dilated CBD on imaging) or ascending cholangitis, not straightforward cholecystitis.', 3),
('c8000000-0000-0000-0000-000000000037', 'Biliary colic reflects transient obstruction of the gallbladder outlet or cystic duct by a gallstone, causing self-limiting pain without the inflammation, fever, or raised inflammatory markers seen in cholecystitis.', 1),
('c8000000-0000-0000-0000-000000000037', 'Normal observations, a normal gallbladder wall on ultrasound, and resolution between episodes distinguish biliary colic from acute cholecystitis.', 2),
('c8000000-0000-0000-0000-000000000037', 'Elective laparoscopic cholecystectomy is recommended for symptomatic gallstones (biliary colic) to prevent recurrent symptoms and complications such as cholecystitis, choledocholithiasis, or pancreatitis.', 3),
('c8000000-0000-0000-0000-000000000038', $x$Charcot's triad (fever, jaundice, right upper quadrant pain) is classically associated with ascending cholangitis due to biliary obstruction and infection; the addition of confusion and hypotension (Reynolds' pentad) indicates more severe, life-threatening disease.$x$, 1),
('c8000000-0000-0000-0000-000000000038', 'Ascending cholangitis is a surgical/medical emergency requiring urgent resuscitation (sepsis six), IV antibiotics, and prompt biliary decompression, typically via ERCP.', 2),
('c8000000-0000-0000-0000-000000000038', 'Obstructive pattern liver function tests (raised bilirubin, ALP, and GGT) support a biliary/obstructive cause rather than a primarily hepatocellular process.', 3),
('c8000000-0000-0000-0000-000000000039', 'Progressive dysphagia (particularly progressing from solids to liquids) combined with weight loss in an older patient is a red-flag combination requiring urgent investigation for oesophageal malignancy.', 1),
('c8000000-0000-0000-0000-000000000039', 'Chronic GORD and smoking are risk factors for oesophageal adenocarcinoma and squamous cell carcinoma respectively, but do not make endoscopic exclusion of cancer any less urgent.', 2),
('c8000000-0000-0000-0000-000000000039', 'Urgent upper GI endoscopy (within 2 weeks) is required for dysphagia with alarm features, rather than an empirical PPI trial, which risks delaying cancer diagnosis.', 3),
('c8000000-0000-0000-0000-000000000040', $x$Barrett's oesophagus is a premalignant condition in which the normal squamous epithelium of the distal oesophagus is replaced by columnar epithelium with intestinal metaplasia, driven by chronic acid reflux.$x$, 1),
('c8000000-0000-0000-0000-000000000040', 'The presence and grade of dysplasia determines the surveillance/treatment strategy - low-grade dysplasia warrants closer endoscopic surveillance (and sometimes endoscopic therapy), while high-grade dysplasia or early cancer usually requires endoscopic or surgical treatment.', 2),
('c8000000-0000-0000-0000-000000000040', $x$Long-term PPI therapy is continued to control reflux and is not stopped simply because Barrett's oesophagus has been diagnosed.$x$, 3),
('c8000000-0000-0000-0000-000000000041', 'In a patient with known liver disease presenting with a major upper GI bleed, variceal haemorrhage should be assumed until proven otherwise, and terlipressin plus prophylactic antibiotics should be started promptly alongside resuscitation, pending urgent endoscopy.', 1),
('c8000000-0000-0000-0000-000000000041', 'Initial management of any major upper GI bleed prioritises airway/circulatory resuscitation (IV access, fluids, blood products, correction of coagulopathy) before endoscopy, following an ABCDE approach.', 2),
('c8000000-0000-0000-0000-000000000041', 'Risk-scoring tools such as the Glasgow-Blatchford score (pre-endoscopy) and Rockall score (post-endoscopy) help guide urgency of intervention and risk of rebleeding/mortality.', 3),
('c8000000-0000-0000-0000-000000000042', 'New dyspepsia/upper GI symptoms with weight loss, iron-deficiency anaemia, or evidence suggestive of GI bleeding (dark stools) in an older adult are red-flag features requiring urgent (2-week wait) referral for endoscopy to exclude gastric or oesophageal cancer.', 1),
('c8000000-0000-0000-0000-000000000042', 'Empirical H. pylori eradication or symptomatic treatment should not be started before excluding malignancy when alarm features are present.', 2),
('c8000000-0000-0000-0000-000000000042', 'Early satiety, unintentional weight loss, and epigastric discomfort are recognised presenting features of gastric cancer, which is often diagnosed late due to non-specific early symptoms.', 3),
('c8000000-0000-0000-0000-000000000043', $x$The '6 Ps' of acute limb ischaemia (pain, pallor, pulselessness, paraesthesia, paralysis, and perishingly cold) indicate a limb-threatening emergency requiring urgent vascular assessment.$x$, 1),
('c8000000-0000-0000-0000-000000000043', 'Atrial fibrillation without anticoagulation is a major risk factor for embolic acute limb ischaemia; sudden onset (as opposed to gradual worsening) favours an embolic rather than thrombotic cause.', 2),
('c8000000-0000-0000-0000-000000000043', 'IV unfractionated heparin should be started promptly to prevent clot propagation while urgent definitive revascularisation (embolectomy, angioplasty, or bypass) is arranged, as sensory/motor deficit indicates a threatened limb needing intervention within hours.', 3),
('c8000000-0000-0000-0000-000000000044', 'Sudden severe abdominal/back pain with hypotension and a pulsatile abdominal mass is the classic triad of a ruptured abdominal aortic aneurysm, a life-threatening surgical emergency.', 1),
('c8000000-0000-0000-0000-000000000044', $x$'Permissive hypotension' (allowing a lower-than-normal blood pressure) is used during resuscitation to avoid dislodging a stabilising clot and worsening haemorrhage before definitive repair.$x$, 2),
('c8000000-0000-0000-0000-000000000044', 'Immediate vascular surgical involvement is essential; a stable patient may sometimes have a confirmatory CT angiogram, but an unstable patient should proceed directly to emergency repair without delay for imaging.', 3),
('c8000000-0000-0000-0000-000000000045', 'The NHS AAA screening programme offers a one-off ultrasound to men in the year they turn 65, aiming to detect aneurysms before rupture.', 1),
('c8000000-0000-0000-0000-000000000045', 'Small aneurysms are managed with regular ultrasound surveillance and cardiovascular risk factor modification (smoking cessation, blood pressure control), with the surveillance interval shortening as the aneurysm enlarges.', 2),
('c8000000-0000-0000-0000-000000000045', 'Referral for elective surgical repair is reserved for larger aneurysms, those that are rapidly expanding, or symptomatic aneurysms, given the risks of intervention must be balanced against rupture risk.', 3),
('c8000000-0000-0000-0000-000000000046', 'Intermittent claudication - cramping leg pain on exertion relieved by rest - is the classic symptom of peripheral arterial disease due to atherosclerotic narrowing of lower limb arteries.', 1),
('c8000000-0000-0000-0000-000000000046', 'The ankle-brachial pressure index is a simple, non-invasive first-line test to confirm and grade the severity of peripheral arterial disease.', 2),
('c8000000-0000-0000-0000-000000000046', 'Management of claudication centres on cardiovascular risk factor modification (smoking cessation, statin, antiplatelet, diabetes and blood pressure control) and a supervised exercise programme, with revascularisation considered for severe or lifestyle-limiting disease.', 3),
('c8000000-0000-0000-0000-000000000047', $x$Amaurosis fugax ('curtain coming down' transient monocular vision loss) is a form of transient ischaemic attack, often due to embolisation from carotid artery disease.$x$, 1),
('c8000000-0000-0000-0000-000000000047', 'Significant (typically 70% or more) symptomatic carotid stenosis is an indication for carotid endarterectomy, ideally performed promptly (within 2 weeks of the event) to reduce the risk of subsequent stroke.', 2),
('c8000000-0000-0000-0000-000000000047', 'All patients with carotid disease should also receive best medical therapy (antiplatelet agent, high-intensity statin, and optimisation of blood pressure and other vascular risk factors) regardless of whether they proceed to surgery.', 3),
('c8000000-0000-0000-0000-000000000048', 'The Wells score stratifies pre-test probability of DVT and guides which investigation pathway to follow (ultrasound first if DVT likely; D-dimer first if DVT unlikely, with ultrasound only if D-dimer is positive).', 1),
('c8000000-0000-0000-0000-000000000048', 'Proximal leg vein ultrasound (compression Doppler) is the definitive first-line imaging investigation when DVT is clinically likely.', 2),
('c8000000-0000-0000-0000-000000000048', 'If ultrasound cannot be performed promptly, interim anticoagulation should be started while awaiting the scan, given the risk of missing or delaying treatment of a DVT.', 3),
('c8000000-0000-0000-0000-000000000049', 'Uncomplicated varicose veins with mild symptoms (aching, heaviness) can often be managed conservatively with compression stockings, leg elevation, and lifestyle advice.', 1),
('c8000000-0000-0000-0000-000000000049', 'Red-flag features warranting referral to vascular services include skin changes (lipodermatosclerosis, venous eczema), healed or active venous ulceration, superficial thrombophlebitis, or bleeding from varicosities.', 2),
('c8000000-0000-0000-0000-000000000049', 'Chronic venous hypertension underlying varicose veins can progress to chronic venous insufficiency, with skin changes and ulceration reflecting more advanced disease requiring specialist assessment for possible intervention (e.g. endovenous ablation).', 3),
('c8000000-0000-0000-0000-000000000050', $x$Arterial ulcers are typically painful, occur at pressure points or the most distal areas (e.g. toes), have a 'punched-out' appearance with a pale/necrotic base, and are associated with absent pulses and other signs of peripheral arterial disease.$x$, 1),
('c8000000-0000-0000-0000-000000000050', 'Pain that worsens on elevation and improves when the leg is dependent (hanging the leg down) reflects poor arterial perfusion, in contrast to venous ulcers which are typically less painful, occur over the medial malleolus, and improve with elevation.', 2),
('c8000000-0000-0000-0000-000000000050', 'Compression bandaging, appropriate for venous ulcers, is contraindicated in significant arterial disease until arterial supply has been assessed (e.g. with ABPI) and optimised, as it can worsen ischaemia.', 3);
